"use strict";

// Suite catalog. A small STATIC list holds the hand-authored/curated suites
// (the built-in Orion suites and manually extracted ones); the bulk imported
// corpora live in corpus/index.json (generated by scripts/seed_corpus_tests.py).
// loadCatalog() merges both. The launcher (popup.js) and runner (runner.js)
// both call it.
//
// Suite entry fields: id, title, group, type ("builtin" | "chrometest"),
// flavors (["chrome"]/["firefox"]/both), minMv/maxMv (upstream manifest version,
// informational), scripts (extension-relative, loaded in order after the
// polyfill), and optional nativeCoop (needs a test server or native message
// peer — expected to fail here).

const STATIC_CATALOG = [
    {
        id: "builtin",
        title: "Orion built-in suites (storage, runtime, i18n, alarms, notifications, errors)",
        group: "Built-in",
        type: "builtin",
        flavors: ["firefox", "chrome"],
        minMv: 2, maxMv: 3,
        scripts: [
            "lib/api.js",
            "lib/test_runner.js",
            "tests/storage.js",
            "tests/runtime.js",
            "tests/i18n.js",
            "tests/alarms.js",
            "tests/notifications.js",
            "tests/errors.js",
        ],
    },
];

async function loadCatalog() {
    let imported = [];
    try {
        const res = await fetch("corpus/index.json");
        if (res.ok) imported = await res.json();
    } catch (e) {
        // index.json is optional (present after seeding); ignore if absent.
    }
    return STATIC_CATALOG.concat(imported);
}

if (typeof window !== "undefined") {
    window.loadCatalog = loadCatalog;
}
